def fast_forte_info(pcs):
    """Return (forte_name, prime_form, interval_vector) for an iterable of pitch classes."""
    key = tuple(sorted(set(pcs)))
    if key in FORTE_DB:
        v = FORTE_DB[key]
        return v["f"], v["p"], v["iv"]
    return "N/A", "[]", "[0 0 0 0 0 0]"
